{
  "name": "opencode-video-gateway",
  "version": "0.1.0",
  "type": "module",
  "private": false,
  "license": "MIT",
  "description": "OpenCode plugin that ingests local or remote videos as direct video attachments or sampled frames.",
  "main": "./src/index.ts",
  "exports": {
    ".": "./src/index.ts"
  },
  "scripts": {
    "test": "bun test",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^1.3.7",
    "@opencode-ai/sdk": "^1.3.7"
  },
  "devDependencies": {
    "@types/bun": "latest",
    "typescript": "^5.9.2"
  }
}

import type { Plugin } from "@opencode-ai/plugin"
import type { Part, TextPart } from "@opencode-ai/sdk"
import { clear, direct, frames, image, media, parse, part, prompt } from "./core"

type Cfg = {
  direct_max_bytes?: number
  frames?: number
}

function text(parts: Part[]) {
  return parts.find((part): part is TextPart => part.type === "text" && !part.synthetic && !part.ignored)
}

export const server: Plugin = async (ctx, raw) => {
  const cfg = (raw ?? {}) as Cfg

  return {
    "chat.message": async (_input, output) => {
      const item = text(output.parts)
      if (!item) return
      const parsed = parse(item.text)
      if (!parsed) return

      const src = await media(parsed.source, ctx.directory)
      const trash: string[] = []
      if (src.cleanup) trash.push(src.cleanup)

      try {
        item.text = prompt(item.text, parsed)

        if (parsed.mode === "direct") {
          const file = await direct(src, cfg)
          output.parts.push(part({ ...file, sessionID: output.message.sessionID, messageID: output.message.id }))
          return
        }

        const set = await frames(src, cfg)
        trash.push(set.cleanup)
        for (const frame of set.items) {
          const file = await image(frame)
          output.parts.push(part({ ...file, sessionID: output.message.sessionID, messageID: output.message.id }))
        }
      } finally {
        await clear(...trash)
      }
    },
  }
}

export default server
